async function uploadFile(sourceUrl, prefix) {
  if (!sourceUrl) return null;
  const urlLower = sourceUrl.toLowerCase();
  const ext = urlLower.includes('.pdf') ? 'pdf' : urlLower.includes('.png') ? 'png' : 'jpg';
  const filename = `${prefix}/${clientId}/${timestamp}.${ext}`;
  const contentType = ext === 'pdf' ? 'application/pdf' : `image/${ext}`;
  try {
    const fileData = await $helpers.httpRequest({ method: 'GET', url: sourceUrl });
    await $helpers.httpRequest({
      method: 'POST',
      url: `https://kvucdlvbxlmvnrzvtcgv.supabase.co/storage/v1/object/ngondet-assets/${filename}`,
      headers: { 'Authorization': `Bearer ${serviceKey}`, 'Content-Type': contentType },
      body: fileData
    });
    return `https://kvucdlvbxlmvnrzvtcgv.supabase.co/storage/v1/object/public/ngondet-assets/${filename}`;
  } catch(e) {
    return sourceUrl; // fallback
  }
}

const [refUrl, visuelUrl] = await Promise.all([
